export const CollapseButton = ({
	messageId,
	collapsedData
}: {
	messageId: string
	collapsedData: Block[]
}) => {
	const [isModalVisible, setIsModalVisible] = useState(false)
	const { theme } = useTheme()
	const currentMessageId = useChatStore((state) => state.value.currentMessageId)
	const chatState = useChatStore((state) => state.value.chatState)

	return (
		<>
			<TouchableOpacity
				style={styles.collapseButtonContainer}
				onPress={() => setIsModalVisible(true)}
			>
				<View style={styles.anythingIconContainer}>
					<AnythingIcon color={colors[theme].gray[900]} />
				</View>
				<Text style={styles.collapseButtonText(theme)}>
					{messageId === currentMessageId && chatState === 'GENERATING'
						? 'Working...'
						: 'See steps'}
				</Text>
				<ChevronRight size={18} color={colors[theme].gray[900]} />
			</TouchableOpacity>
			<Modal
				presentationStyle="formSheet"
				animationType="slide"
				allowSwipeDismissal
				visible={isModalVisible}
				onRequestClose={() => setIsModalVisible(false)}
				backdropColor={colors[theme].gray[25]}
			>
				<DetailedSteps collapsedData={collapsedData} />
			</Modal>
		</>
	)
}

const styles = defineStyles({
	collapseButtonContainer: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 8,
		paddingLeft: 28
	},
	anythingIconContainer: {
		width: 18,
		height: 18,
		position: 'absolute',
		left: 0,
		top: 0
	},
	collapseButtonText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900]
	})
})
